    14	/** Password change (by the user) and password reset (by an administrator). */
    15	public class PasswordService {
    16	    private final AccountStore accounts;
    17	    private final SessionStore sessions;
    18	    private final PasswordHasher hasher;
    19	    private final PasswordHistoryGuard historyGuard;
    20	    private final PasswordPolicy policy;
    21	    private final Clock clock;
    22	
    23	    public PasswordService(AccountStore accounts, SessionStore sessions, PasswordHasher hasher,
    24	                           PasswordHistoryGuard historyGuard, PasswordPolicy policy, Clock clock) {
    25	        this.accounts = accounts;
    26	        this.sessions = sessions;
    27	        this.hasher = hasher;
    28	        this.historyGuard = historyGuard;
    29	        this.policy = policy;
    30	        this.clock = clock;
    31	    }
    32	
    33	    public void change(String accountId, String currentPassword, String newPassword) {
    34	        Account account = accounts.findById(accountId)
    35	                .orElseThrow(() -> ValidationException.of(404, "account not found"));
    36	        if (!hasher.matches(currentPassword, account.passwordHash())) {
    37	            throw ValidationException.of(403, "current password is incorrect");
    38	        }
    39	        apply(account, newPassword);
    40	    }
    41	
    42	    public void adminReset(String accountId, String newPassword) {
    43	        Account account = accounts.findById(accountId)
    44	                .orElseThrow(() -> ValidationException.of(404, "account not found"));
    45	        apply(account, newPassword);
    46	        sessions.removeAllFor(accountId);
    47	    }
    48	
    49	    private void apply(Account account, String newPassword) {
    50	        List<String> problems = new ArrayList<>();
    51	        for (PolicyViolation v : policy.check(account.username(), newPassword)) {
    52	            problems.add(v.message());
    53	        }
    54	        if (problems.isEmpty() && historyGuard.usedRecently(account.id(), newPassword, policy.reuseWindow())) {
    55	            problems.add(PolicyViolation.RECENTLY_USED.message());
    56	        }
    57	        if (!problems.isEmpty()) {
    58	            throw new ValidationException(422, problems);
    59	        }
    60	        String hash = hasher.hash(newPassword);
    61	        accounts.save(account.withPassword(hash, clock.instant()));
    62	        historyGuard.remember(account.id(), hash);
    63	    }
