     1	package store;
     2	
     3	import java.util.ArrayList;
     4	import java.util.HashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	
     8	/** Password hashes per account, oldest first. The newest entry is the current password. */
     9	public class CredentialHistoryStore {
    10	    static final int MAX_ENTRIES = 24;
    11	
    12	    private final Map<String, List<String>> history = new HashMap<>();
    13	
    14	    public synchronized void append(String accountId, String passwordHash) {
    15	        List<String> entries = history.computeIfAbsent(accountId, k -> new ArrayList<>());
    16	        entries.add(passwordHash);
    17	        if (entries.size() > MAX_ENTRIES) {
    18	            entries.subList(0, entries.size() - MAX_ENTRIES).clear();
    19	        }
    20	    }
    21	
    22	    /** The {@code count} most recent hashes, newest first. */
    23	    public synchronized List<String> recent(String accountId, int count) {
    24	        List<String> entries = history.getOrDefault(accountId, List.of());
    25	        List<String> result = new ArrayList<>();
    26	        for (int i = entries.size() - 1; i >= 0 && result.size() < count; i--) {
    27	            result.add(entries.get(i));
    28	        }
    29	        return result;
    30	    }
    31	
    32	    public synchronized int size(String accountId) {
    33	        return history.getOrDefault(accountId, List.of()).size();
    34	    }
    35	}
