     1	package crypto;
     2	
     3	import java.nio.charset.StandardCharsets;
     4	import java.security.MessageDigest;
     5	import java.security.NoSuchAlgorithmException;
     6	import java.security.SecureRandom;
     7	import java.util.Base64;
     8	
     9	/** Salted SHA-256, stored as {@code salt$digest} (both base64). */
    10	public final class PasswordHasher {
    11	    private static final int SALT_BYTES = 16;
    12	    private static final int ROUNDS = 1_000;
    13	
    14	    private final SecureRandom random = new SecureRandom();
    15	
    16	    public String hash(String raw) {
    17	        byte[] salt = new byte[SALT_BYTES];
    18	        random.nextBytes(salt);
    19	        return encode(salt) + "$" + encode(digest(salt, raw));
    20	    }
    21	
    22	    public boolean matches(String raw, String stored) {
    23	        if (raw == null || stored == null) {
    24	            return false;
    25	        }
    26	        int sep = stored.indexOf('$');
    27	        if (sep <= 0) {
    28	            return false;
    29	        }
    30	        byte[] salt = Base64.getDecoder().decode(stored.substring(0, sep));
    31	        byte[] expected = Base64.getDecoder().decode(stored.substring(sep + 1));
    32	        return MessageDigest.isEqual(expected, digest(salt, raw));
    33	    }
    34	
    35	    private static byte[] digest(byte[] salt, String raw) {
    36	        try {
    37	            MessageDigest md = MessageDigest.getInstance("SHA-256");
    38	            byte[] out = raw.getBytes(StandardCharsets.UTF_8);
    39	            for (int i = 0; i < ROUNDS; i++) {
    40	                md.reset();
    41	                md.update(salt);
    42	                md.update(out);
    43	                out = md.digest();
    44	            }
    45	            return out;
    46	        } catch (NoSuchAlgorithmException e) {
    47	            throw new IllegalStateException(e);
    48	        }
    49	    }
    50	
    51	    private static String encode(byte[] bytes) {
    52	        return Base64.getEncoder().withoutPadding().encodeToString(bytes);
    53	    }
    54	}
