    26	        this(MIN_LENGTH, REQUIRE_DIGIT, REUSE_WINDOW);
    27	    }
    28	
    29	    public PasswordPolicy(int minLength, boolean requireDigit, int reuseWindow) {
    30	        this.minLength = minLength;
    31	        this.requireDigit = requireDigit;
    32	        this.reuseWindow = reuseWindow;
    33	    }
    34	
    35	    public int minLength() {
    36	        return minLength;
    37	    }
    38	
    39	    /** How many of the most recent passwords (current one included) may not be chosen again. */
    40	    public int reuseWindow() {
    41	        return reuseWindow;
    42	    }
    43	
    44	    /** Checks the shape of a candidate password. History is checked separately. */
    45	    public List<PolicyViolation> check(String username, String candidate) {
    46	        List<PolicyViolation> violations = new ArrayList<>();
    47	        if (candidate == null || candidate.length() < minLength) {
    48	            violations.add(PolicyViolation.TOO_SHORT);
    49	            return violations;
    50	        }
    51	        if (requireDigit && candidate.chars().noneMatch(Character::isDigit)) {
    52	            violations.add(PolicyViolation.MISSING_DIGIT);
    53	        }
    54	        if (username != null && !username.isBlank()
    55	                && candidate.toLowerCase(Locale.ROOT).contains(username.toLowerCase(Locale.ROOT))) {
    56	            violations.add(PolicyViolation.CONTAINS_USERNAME);
    57	        }
    58	        return violations;
    59	    }
    60	}

